use rig::prelude::*;
use rig::providers::anthropic::{self, Anthropic};


// Reads ANTHROPIC_API_KEY (and ANTHROPIC_BASE_URL, if set).
let client = Anthropic::from_env()?;


let agent = AgentBuilder::new(client.completion(anthropic::CLAUDE_SONNET_5_5))
    .preamble("You are a helpful assistant.")
    .build();


let answer = agent.prompt("Hello!").await?.output();
println!("{answer}");

use rig::providers::anthropic::{Anthropic, AnthropicConfig};
use rig::providers::anthropic::extension::CONTEXT_MANAGEMENT_BETA;


// From ANTHROPIC_API_KEY and the optional ANTHROPIC_BASE_URL.
let client = Anthropic::from_env()?;


// From an explicit key.
let client = Anthropic::new("your-api-key");


// From a configuration: pin the API version, opt into beta features,
// or point at another API root.
let client = AnthropicConfig::new("your-api-key")
    .with_version("2023-06-01")
    .with_beta(CONTEXT_MANAGEMENT_BETA)
    .with_base_url("https://anthropic-proxy.example.com")
    .client();

use rig::completion::{Effort, Reasoning};
use rig::prelude::*;
use rig::providers::anthropic::{self, Anthropic};


let client = Anthropic::from_env()?;


// An effort level, for models that take one.
let agent = AgentBuilder::new(client.completion(anthropic::CLAUDE_OPUS_4_8))
    .reasoning(Effort::High)
    .build();


// An explicit thinking budget, for models that take one.
let budgeted = AgentBuilder::new(client.completion(anthropic::CLAUDE_HAIKU_4_5))
    .reasoning(Reasoning::Budget { tokens: 8_000 })
    .build();

use rig::completion::CacheRetention;
use rig::prelude::*;
use rig::providers::anthropic::{self, Anthropic};


let agent = AgentBuilder::new(Anthropic::from_env()?.completion(anthropic::CLAUDE_SONNET_5_5))
    .preamble("A long, stable system prompt...")
    .cache(CacheRetention::Short)
    .build();

use rig::completion::CacheRetention;
use rig::prelude::*;
use rig::providers::anthropic::{self, Anthropic, completion::CacheTtl};


let mut model = Anthropic::from_env()?.completion(anthropic::CLAUDE_SONNET_5_5);
model.wire = model
    .wire
    .with_prompt_caching()
    .with_static_prefix_cache_ttl(CacheTtl::OneHour);


let agent = AgentBuilder::new(model)
    .preamble("A long, stable system prompt...")
    .cache(CacheRetention::Long) // the conversation tail's TTL
    .build();

use rig::prelude::*;
use rig::providers::anthropic::extension::{AnthropicOptions, InferenceGeo};
use rig::providers::anthropic::{self, Anthropic};


let options = AnthropicOptions::default()
    .metadata_user_id("user-7")
    .inference_geo(InferenceGeo::Us);


let agent = AgentBuilder::new(Anthropic::from_env()?.completion(anthropic::CLAUDE_SONNET_5_5))
    .provider_option(options)
    .build();

use rig::completion::CompletionRequest;
use rig::providers::anthropic::extension::AnthropicExt;
use rig::providers::anthropic::{self, Anthropic};


let model = Anthropic::from_env()?.completion(anthropic::CLAUDE_HAIKU_4_5);
let response = model.call(CompletionRequest::new("Say hi.")).await?;


println!("{}", response.text());
println!("cache reads: {:?}", response.usage.cached_input_tokens);
if let Some(Ok(extras)) = response.extras::<AnthropicExt>() {
    println!("stop reason: {:?}", extras.stop_reason);
}
